#!/usr/bin/env node
/**
 * generate-public-creds.mjs — pure codegen: config/public-creds.json -> src/shared/utils/publicCreds.generated.ts
 *
 * The source JSON holds plaintext public upstream credentials and is gitignored.
 * The generated file holds only XOR-masked bytes and IS committed, so fresh clones and CI
 * build without the JSON. When the JSON is absent, the committed generated file is left untouched.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT_DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const CONFIG_PATH = path.join(ROOT_DIR, "config", "public-creds.json");
const OUTPUT_PATH = path.join(ROOT_DIR, "src", "shared", "utils", "publicCreds.generated.ts");
const MASK = "mapigate-public-v1";
const TAG = "[codegen:public-creds]";

function maskBytes(plain) {
  return Array.from(plain, (ch, i) => ch.charCodeAt(0) ^ MASK.charCodeAt(i % MASK.length));
}

if (!fs.existsSync(CONFIG_PATH)) {
  if (fs.existsSync(OUTPUT_PATH)) {
    console.log(`${TAG} config/public-creds.json not found, keeping committed ${path.basename(OUTPUT_PATH)}`);
    process.exit(0);
  }
  console.error(`${TAG} Neither config/public-creds.json nor ${path.basename(OUTPUT_PATH)} exists.`);
  console.error(`${TAG} Copy config/public-creds.example.json to config/public-creds.json and fill in real values.`);
  process.exit(1);
}

let config;
try {
  config = JSON.parse(fs.readFileSync(CONFIG_PATH, "utf-8"));
} catch (err) {
  console.error(`${TAG} Invalid JSON in config/public-creds.json: ${err.message}`);
  process.exit(1);
}

const entries = Object.entries(config).sort(([a], [b]) => a.localeCompare(b));
const invalid = entries.filter(([, v]) => typeof v !== "string" || v.trim() === "");
if (entries.length === 0 || invalid.length > 0) {
  console.error(`${TAG} Every entry must be a non-empty string. Invalid: ${invalid.map(([k]) => k).join(", ") || "(empty file)"}`);
  process.exit(1);
}

const body = entries.map(([key, val]) => `  ${key}: [${maskBytes(val.trim()).join(", ")}],`).join("\n");
const content = `/**
 * AUTO-GENERATED by scripts/generate-public-creds.mjs from config/public-creds.json — DO NOT EDIT.
 * XOR-masked public upstream credentials, decoded at runtime by resolvePublicCred() in publicCreds.ts.
 */

export const PUBLIC_CREDS_MASK = ${JSON.stringify(MASK)};

export const MASKED_PUBLIC_CREDS = {
${body}
} as const satisfies Record<string, readonly number[]>;

export type PublicCredKey = keyof typeof MASKED_PUBLIC_CREDS;
`;

fs.mkdirSync(path.dirname(OUTPUT_PATH), { recursive: true });
fs.writeFileSync(OUTPUT_PATH, content, "utf-8");
console.log(`${TAG} Generated ${entries.length} masked credentials`);
